def build(output_dir=None):
    base = Path(output_dir or Path.cwd()).resolve()
    root = base / 'document-editor-app'
    root.mkdir(parents=True, exist_ok=True)
    for relative, content in FILES.items():
        target = root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding='utf-8')
    (root / 'build_repo.py').write_text(Path(__file__).read_text(encoding='utf-8'), encoding='utf-8')
    archive_path = base / 'document-editor-app.zip'
    with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as archive:
        for path in sorted(root.rglob('*')):
            if path.is_file():
                archive.write(path, Path('document-editor-app') / path.relative_to(root))
    print(f'Created {root} and {archive_path}')
    return archive_path

if __name__ == '__main__':
    build()
